        // We need to map file offsets to virtual addresses
        // The segment starts at p_offset in the file and maps to p_vaddr in memory

        // For simplicity, we'll read the segment data and map it to virtual addresses
        // The segment data starts at p_offset and has size filesz
        // The virtual addresses start at p_vaddr

        // We need to handle the case where filesz < memsz (bss section)
        // For bss, we can't read actual values, so we skip or set to 0

        const fileOffset = p_offset;
        const virtualBase = p_vaddr;

        // Read the segment data
        for (let j = 0; j < filesz; j += 4) {
            if (j + 4 <= filesz) {
                const value = data.readUInt32LE(fileOffset + j);
                const addr = virtualBase + j;
                output[addr.toString()] = value;
            }
        }
    }
