for (let i = 0; i < e_phnum; i++) {
    const p_type = data.readUInt32LE(phoff);
    const p_offset = data.readUInt32LE(phoff + 4);
    const p_vaddr = data.readUInt32LE(phoff + 8);
    const p_paddr = data.readUInt32LE(phoff + 12);
    const p_filesz = data.readUInt32LE(phoff + 16);
