const fs = require('fs');
const readline = require('readline');

async function main() {
    const args = process.argv.slice(2);
    if (args.length < 1) {
        console.error('Usage: node extract.js <binary>');
        process.exit(1);
    }

    const binaryPath = args[0];
    const buffer = fs.readFileSync(binaryPath);

    const result = {};

    // Read ELF header to get machine type and entry point
    const elfClass = buffer[4]; // 1 = 32-bit, 2 = 64-bit
    const elfData = buffer[5]; // 1 = little endian, 2 = big endian
    const elfType = buffer[16]; // 1 = executable, 2 = shared object
    const elfMachine = buffer[18]; // 3 = i386, 40 = x86-64

    let endian = elfData === 1 ? 'little' : 'big';

    // Read entry point
    let entryPoint;
    if (elfClass === 2) {
        // 64-bit
        entryPoint = buffer.readBigUInt64LE(24);
    } else {
        // 32-bit
        entryPoint = buffer.readUInt32LE(24);
    }

    // Read program headers
    const e_phoff = elfClass === 2 ? buffer.readBigUInt64LE(32) : buffer.readUInt32LE(32);
    const e_phentsize = elfClass === 2 ? buffer.readUInt16LE(42) : buffer.readUInt16LE(36);
    const e_phnum = elfClass === 2 ? buffer.readUInt16LE(44) : buffer.readUInt16LE(38);

    const phdrs = [];
    for (let i = 0; i < e_phnum; i++) {
        const offset = e_phoff + i * e_phentsize;
        const p_type = elfClass === 2 ? buffer.readBigUInt32LE(offset) : buffer.readUInt32LE(offset);
        const p_offset = elfClass === 2 ? buffer.readBigUInt64LE(offset + 8) : buffer.readUInt32LE(offset + 8);
        const p_vaddr = elfClass === 2 ? buffer.readBigUInt64LE(offset + 16) : buffer.readUInt32LE(offset + 16);
        const p_filesz = elfClass === 2 ? buffer.readBigUInt64LE(offset + 32) : buffer.readUInt32LE(offset + 32);
        const p_memsz = elfClass === 2 ? buffer.readBigUInt64LE(offset + 40) : buffer.readUInt32LE(offset + 40);

        phdrs.push({
            type: p_type,
            offset: p_offset,
            vaddr: p_vaddr,
            filesz: p_filesz,
            memsz: p_memsz
        });
    }

    // Process PT_LOAD segments
    for (const phdr of phdrs) {
        if (phdr.type !== 1) continue; // PT_LOAD

        const startAddr = phdr.vaddr;
        const endAddr = startAddr + phdr.memsz;

        // Read the segment from file
        const segmentData = buffer.slice(phdr.offset, phdr.offset + phdr.filesz);

        // Calculate the file offset for each address
        const fileOffset = (startAddr - phdr.vaddr) + phdr.offset;

        // Read memory values
        for (let addr = startAddr; addr < endAddr; addr += 4) {
            const fileOffsetForAddr = (addr - startAddr) + phdr.offset;
            if (fileOffsetForAddr + 4 <= buffer.length) {
                let value;
                if (endian === 'little') {
                    value = buffer.readUInt32LE(fileOffsetForAddr);
                } else {
                    value = buffer.readUInt32BE(fileOffsetForAddr);
                }
                result[addr.toString()] = value;
            }
        }
    }

    // Output as JSON
    console.log(JSON.stringify(result));
}

